import sys
from collections import defaultdict, deque

def read_ints():
    return list(map(int, sys.stdin.readline().split()))

def main():
    import sys
    import threading
    def solve():
        t = int(sys.stdin.readline())
        results = []
        for _ in range(t):
            n, k = read_ints()
            friends = read_ints()
            edges = [tuple(read_ints()) for _ in range(n - 1)]

            # Build the graph
            graph = defaultdict(list)
            for u, v in edges:
                graph[u].append(v)
                graph[v].append(u)

            # Find leaves
            leaves = [node for node in range(1, n + 1) if len(graph[node]) == 1]
            leaf_set = set(leaves)

            # Remove friends from leaves
            friends_set = set(friends)
            remaining_leaves = leaf_set - friends_set

            # If there are no leaves left after removing friends, Vlad wins
            if not remaining_leaves:
                results.append(-1)
                continue

            # BFS to find the farthest leaf from room 1
            queue = deque([1])
            visited = {1}
            farthest_leaf = None
            while queue:
                node = queue.popleft()
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append(neighbor)
                        farthest_leaf = neighbor

            # Check if the farthest leaf is a leaf with a friend
            if farthest_leaf in friends_set:
                results.append(1)
            else:
                results.append(2)

        for result in results:
            print(result)

    threading.Thread(target=solve).start()

if __name__ == "__main__":
    main()
